# Import of required libraries
import skyramp
import json
import os
import re
import time

from SkyrampUtils import create_category, create_recipe, update_recipe, get_recipes_list


# URL for test requests
URL_localhost = skyramp.get_base_url("SKYRAMP_TEST_BASE_URL", "http://localhost:9000")


def test_integration():
    # Invocation of Skyramp Client
    client = skyramp.Client()
    # Definition of authentication header
    headers = {}
    if os.getenv("SKYRAMP_TEST_TOKEN") is not None:
        headers["Authorization"] = "Bearer " + os.getenv("SKYRAMP_TEST_TOKEN")

    # Declaration of variables
    perPage = "1"

    categories_POST_response = create_category(
        client, headers, skyramp.unique_suffix("Pagination Integrity Cat")
    )

    category_name_sent = skyramp.get_response_value(categories_POST_response, "name")
    assert skyramp.get_response_value(categories_POST_response, "name") == category_name_sent
    assert re.match(
        r"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$",
        skyramp.get_response_value(categories_POST_response, "id"),
        re.IGNORECASE,
    )
    assert skyramp.get_response_value(categories_POST_response, "slug") is not None

    category_id = skyramp.get_response_value(categories_POST_response, "id")
    category_slug = skyramp.get_response_value(categories_POST_response, "slug")
    category_name = skyramp.get_response_value(categories_POST_response, "name")

    categorized_recipe_name = skyramp.unique_suffix("Categorized Paging Recipe")
    recipes_POST_response = create_recipe(client, headers, categorized_recipe_name)

    # POST /api/recipes returns the new recipe slug as a bare JSON string
    recipes = json.loads(recipes_POST_response.response_body)
    assert isinstance(recipes, str) and recipes.startswith("categorized-paging-recipe")

    recipes_recipes_PATCH_response = update_recipe(
        client,
        headers,
        recipes,
        [{"id": category_id, "name": category_name, "slug": category_slug}],
        name=categorized_recipe_name,
    )

    # The categorized recipe really carries exactly the category created in step 1
    assert skyramp.get_response_value(recipes_recipes_PATCH_response, "name") == categorized_recipe_name
    assert skyramp.get_response_value(recipes_recipes_PATCH_response, "slug") == recipes

    patched_categories = json.loads(recipes_recipes_PATCH_response.response_body)["recipeCategory"]
    assert len(patched_categories) == 1
    assert patched_categories[0]["id"] == category_id
    assert patched_categories[0]["slug"] == category_slug

    # Created last, so this uncategorized recipe is the newest under created_at desc
    recipes_POST_1_response = create_recipe(
        client, headers, skyramp.unique_suffix("Uncategorized Paging Recipe")
    )

    recipes_GET_response = get_recipes_list(
        client,
        headers,
        {
            "categories_only": ["true"],
            "orderBy": ["created_at"],
            "orderDirection": ["desc"],
            "page": [perPage],
            "perPage": [perPage]
        },
    )

    page = json.loads(recipes_GET_response.response_body)

    # the response reflects the pagination parameters that were sent
    assert page["page"] == int(perPage)
    assert page["per_page"] == int(perPage)
    assert len(page["items"]) <= int(perPage)

    # categories_only must be applied by the query that pages the data, not to the page
    # slice after it. The newest recipe is uncategorized, so a post-pagination filter
    # empties page 1 and hides the categorized recipe entirely.
    assert len(page["items"]) == 1, (
        "page 1 is empty: the uncategorized newest recipe consumed the page slot, "
        "so categories_only was applied after pagination instead of inside the query"
    )
    assert page["items"][0]["recipeCategory"], (
        "categories_only=true returned a recipe with no category"
    )

    # total must count every matching recipe, not just the ones left on this page
    assert page["total"] >= 1, (
        "total is 0 while at least one categorized recipe exists — total was "
        "overwritten with the post-filter length of the current page"
    )
    assert page["total_pages"] == -(-page["total"] // page["per_page"]), (
        "total_pages is inconsistent with total/per_page"
    )
    if page["total"] <= page["per_page"]:
        assert page["next"] is None, (
            "next advertises a further page although total fits on this one"
        )


if __name__ == "__main__":
    test_integration()
